import { useForm, toast } from "march/ui"
import { Wizard } from "march/components/wizard"

// üç adımda bir kahve: boy, süt ve bardağa yazılacak ad; son adım siparişi verir
export function CoffeeWizard() {
  let $order = ""
  // march/ui'de useForm bir alan tanımından formu kurar; Wizard bu formun alanlarını adım adım gösterir
  const form = useForm({
    size: { type: "pick", label: "Boy", options: ["Küçük", "Orta", "Büyük"], default: "Orta" },
    milk: { type: "pick", label: "Süt", options: ["Sütsüz", "İnek sütü", "Yulaf sütü"], default: "Yulaf sütü" },
    name: { type: "text", label: "Bardağa yazılacak ad", required: true },
  }, {}, { onSubmit: (v) => { $order = `☕ ${v.name}: ${v.size} boy, ${v.milk}`; toast("Kahven hazırlanıyor") } })
  return <div sx={{ flex: "col", gap: 2 }}>
    <Wizard form={form} submitLabel="Sipariş ver" m:color="brand-orange"
      steps={[{ title: "Boy", fields: ["size"] }, { title: "Süt", fields: ["milk"] }, { title: "Ad", fields: ["name"] }]} />
    <span sx={{ text: "lg", color: $order ? "brand-orange" : "muted" }}>{$order || "Henüz sipariş yok"}</span>
  </div>
}

import { useForm, Button, Badge, Card } from "march/ui"
import { Wizard, type WizardApi } from "march/components/wizard"

// Wizard'ın bütün özellikleri: şema ve başlangıç değerleri, adım başına alanlar ve ek doğrulama (alan hatası ya da
// adım mesajı), kendi gövdesi olan bir özet adımı, ızgara düzen, anında hata (validateOn), adım olayı (onStep),
// dışarıdan gezinme (onReady), kendi metinler, sınıf; altta var olan bir formla (form) parçaları kapalı ikinci sihirbaz
export function WizardLab() {
  let $step = 0
  let $done = ""
  let $invited = ""
  let api: WizardApi | undefined
  // march/ui'de schema() yok: useForm bir alan tanımından şemayı kurar, Wizard'a o şema verilir
  const shop = useForm({
    shop: { type: "text", label: "Mağaza adı", required: true },
    city: { type: "text", label: "Şehir" },
    plan: { type: "pick", label: "Paket", options: ["Başlangıç", "Pro"] },
    seats: { type: "int", label: "Kişi", min: 1, max: 50 },
  }).schema
  const invite = useForm({ email: { type: "email", label: "Davet e-postası", required: true } }, {},
    { onSubmit: (v) => { $invited = `${v.email} davet edildi` } })
  return <div sx={{ flex: "col", gap: 3 }}>
    <Wizard schema={shop} initial={{ city: "İzmir", plan: "Pro", seats: 3 }} validateOn="change" layout="grid" cols={2}
      class="lab-wizard" submitLabel="Mağazayı aç" m:color="brand-purple"
      labels={{ back: "← Geri", next: "İleri →", step: (i) => `Bölüm ${i + 1}`, count: (i, n) => `${i + 1} / ${n}` }}
      onStep={(i) => $step = i} onReady={(_, a) => { api = a }}
      onSubmit={(v) => { $done = `${v.shop} açıldı (${v.plan}, ${v.seats} kişi)` }}
      steps={[
        { title: "Mağaza", description: "Adı ve şehri", fields: ["shop", "city"],
          validate: (v) => (v.shop === "test" ? { shop: "Bu ad ayrılmış" } : null) },
        { fields: ["plan", "seats"],
          validate: (v) => (v.plan === "Başlangıç" && Number(v.seats) > 5 ? "Başlangıç paketi en çok 5 kişilik" : null) },
        { title: "Özet", render: (f) => <p sx={{ text: "lg" }}>{() => `${f.values.shop} · ${f.values.city} · ${f.values.plan}`}</p> },
      ]} />
    <div sx={{ flex: ["row", "wrap", "center"], gap: 2 }}>
      <Badge tone="primary">{`Adım ${$step + 1}`}</Badge>
      <Button size="sm" variant="ghost" on:click={() => api?.go(2)}>Özete atla</Button>
      <span sx={{ color: "success" }}>{$done}</span>
    </div>
    <Card m:theme="night">
      <Wizard form={invite} stepper={false} progress={false} count={false} backButton={false} submitLabel="Davet gönder"
        steps={[{ title: "Ekip arkadaşını davet et", fields: ["email"] }]} />
      <span sx={{ color: "brand-gold" }}>{$invited}</span>
    </Card>
  </div>
}

import { test, expect, renderTest } from "march/testing"
import { WizardLab } from "./WizardLab.tsx"

// WizardLab'in testleri: kaydedince Testler sekmesinde çalışır. İleri düğmesi formu gönderir (submit): s.submit aynısını yapar
const next = ".lab-wizard"

test("zorunlu ad boşken İleri ilk adımda kalır", async () => {
  const s = renderTest(() => <WizardLab />)
  await s.submit(next)
  expect(s.sees("1 / 3")).toBe(true)
  expect(s.sees("Adım 1")).toBe(true)
})

test("adın ek doğrulaması alan hatası verir", async () => {
  const s = renderTest(() => <WizardLab />)
  await s.type("shop", "test")
  await s.submit(next)
  expect(s.sees("Bu ad ayrılmış")).toBe(true)
  expect(s.sees("Adım 1")).toBe(true)
})

test("ad yazılınca ikinci adıma geçer; başlıksız adımın adı labels.step'ten gelir", async () => {
  const s = renderTest(() => <WizardLab />)
  await s.type("shop", "Kahve Durağı")
  await s.submit(next)
  expect(s.sees("2 / 3")).toBe(true)
  expect(s.get(".lab-wizard .m-wizard-title")?.textContent).toBe("Bölüm 2")
  expect(s.sees("Adım 2")).toBe(true)
})

test("onReady'nin go'su özete atlar; Mağazayı aç onSubmit'i çalıştırır", async () => {
  const s = renderTest(() => <WizardLab />)
  await s.type("shop", "Kahve Durağı")
  await s.click("Özete atla")
  expect(s.sees("Kahve Durağı · İzmir · Pro")).toBe(true)
  await s.submit(next)
  await s.wait(() => s.sees("Kahve Durağı açıldı (Pro, 3 kişi)"))
  expect(s.sees("Kahve Durağı açıldı")).toBe(true)
})
